        <div key={char} className="text-center">
          <div
            className="bg-white/20 mx-auto"
            style={{ height: `${(freq / max) * 100}px`, width: "12px" }}
          ></div>
          <div>{char}</div>
        </div>
      ))}
    </div>
  );
};

  const decryptCaesar = (text, shift) => {
    let result = "";
    for (let char of text.toUpperCase()) {
      if (/[A-Z]/.test(char)) {
        let index = (char.charCodeAt(0) - 65 - shift + 26) % 26;
        result += String.fromCharCode(index + 65);
      } else {
        result += char;
      }
    }
    return result;
  };

  const applyErsetzung = (text, zuordnung) => {
    let result = "";
    const mapping = {};
    zuordnung.forEach((klarChar, idx) => {
      const geheimChar = klartextAlphabet[idx];
      if (klarChar) {
        mapping[geheimChar] = klarChar;
      }
    });
    for (let c of text.toUpperCase()) {
      result += mapping[c] || c;
    }
    return result;
  };

  const haeufigkeitsbasiertesAlphabet = () => {
    const freq = analyseHaeufigkeit(ersetzenText);
    const geheimHaeufigkeit = Object.entries(freq).sort((a, b) => b[1] - a[1]).map(([c]) => c);
    const zuordnung = Array(26).fill("");
    geheimHaeufigkeit.forEach((c, i) => {
      if (i < haeufigkeitDeutsch.length) {
        const geheimIndex = klartextAlphabet.indexOf(c);
        if (geheimIndex !== -1) {
          zuordnung[geheimIndex] = haeufigkeitDeutsch[i];
        }
      }
    });
    return zuordnung;
  };

  const updateKlartextBuchstabe = (index, value) => {
    const newZuordnung = [...klartextZuordnung];
    newZuordnung[index] = value.toUpperCase();
    setKlartextZuordnung(newZuordnung);
  };

  const getGeheimAlphabet = (shift) => {
    return klartextAlphabet.map((_, i) => klartextAlphabet[(i + shift) % 26]);
  };

  return (
    <div className="text-style">
      <h1 className="text-2xl font-bold heading-style mb-4">Let's see what we have...</h1>
      <p className="mb-4">
        Du hast dir in Bagdad ein Zimmer gemietet, um über das nachzudenken, was du inzwischen gelernt hast.
        Das Verschiebeverfahren war noch nicht besonders sicher – doch wie sieht es mit dem Ersetzungsverfahren aus?
        Du beschließt, zunächst nochmal einen Blick auf das Caesar-Verfahren zu werfen...
      </p>

      <div className="mb-8">
        <h2 className="text-xl font-bold heading-style mb-2">Kryptoanalyse beim Verschiebeverfahren</h2>
        <p> Du erinnerst dich daran, dass das Caesar-Verfahren nur eine Verschiebung des Alphabets ist und daher nur 26 mögliche Schlüssel existieren.
            Durch Ausprobieren aller Schlüssel solltest du also jede Nachricht entschlüsseln können.
            Probiere nun für die folgende Nachricht alle 26 möglichen Schlüssel durch, um die Chiffre zu knacken:
            </p>
        <textarea
          value={verschiebeText}
          onChange={(e) => setVerschiebeText(e.target.value)}
          className="w-full p-2 text-black rounded mb-2"
          rows={2}
        />
        <div className="flex items-center justify-center gap-4 mb-2">
          <button onClick={() => setCaesarShift((caesarShift + 25) % 26)} className="px-2 py-1 border rounded">⬅</button>
          <div className="text-center">
            <div><strong><b>Schlüssel:</b></strong> {klartextAlphabet[caesarShift]}</div>
            <div><strong><b>Verschiebezahl:</b></strong> {caesarShift}</div>
            <table className="table-fixed text-sm border mt-2">
              <thead>
                <tr>
                  {klartextAlphabet.map((char, i) => (
                    <th key={i} className="border w-7 h-7">{char}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr>
                  {getGeheimAlphabet(caesarShift).map((char, i) => (
                    <td key={i} className="border text-center w-7 h-7">{char}</td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
          <button onClick={() => setCaesarShift((caesarShift + 1) % 26)} className="px-2 py-1 border rounded">➡</button>
        </div>
        <div className="bg-white/10 p-4 rounded text-sm mb-4">
          {decryptCaesar(verschiebeText, caesarShift)}
        </div>
        <p>Das Ausprobieren funktioniert problemlos, aber du erkennst, dass es auch einen systematischen Weg gibt, das Caesar-Verfahren zu knacken.
            Dafür zählst du die Häufigkeit der Buchstaben im Geheimtext und bildest die Buchstaben entsprechend der Häufigkeit in der Klartext-Sprache aufeinander ab.
            Wenn du also herausfindest, welche Buchstaben im Geheimtext besonders häufig vorkommen, kannst du versuchen, diese mit den häufigsten Buchstaben in Klartexten zu vergleichen.
          Am häufigsten ist im Deutschen z. B. das „E“, gefolgt von „N“, „I“, „S“ usw. Im Deutschen finden sich die folgenden Buchstabenhäufigkeiten:</p>
          {renderDeutscheHaeufigkeitBalken()}
        <p><br></br>Nun betrachtest du nochmal die verschlüsselte Botschaft:</p>
        <div className="bg-white/10 p-4 rounded text-sm mb-4">
          {verschiebeText}
        </div>
        <button
          onClick={() => setShowCaesarFreq(!showCaesarFreq)}
          className="mb-2 px-4 py-2 border border-white text-white rounded hover:bg-white hover:text-black transition"
        >
          Buchstabenhäufigkeit anzeigen
        </button>
        {showCaesarFreq && renderHaeufigkeitBalken(analyseHaeufigkeit(verschiebeText), true)}
      </div>

      <div className="mb-8">
        <h2 className="text-xl font-bold heading-style mb-2">Kryptoanalyse beim Ersetzungsverfahren</h2>
        <textarea
          value={ersetzenText}
          onChange={(e) => setErsetzenText(e.target.value)}
          className="w-full p-2 text-black rounded mb-2"
          rows={6}
        />
        <button
          onClick={() => setShowSubFreq(!showSubFreq)}
          className="mb-2 px-4 py-2 border border-white text-white rounded hover:bg-white hover:text-black transition"
        >
          Buchstabenhäufigkeit anzeigen
        </button>
        {showSubFreq && renderHaeufigkeitBalken(analyseHaeufigkeit(ersetzenText))}
        <p className="mt-4 font-bold">Klartextalphabet ermitteln:</p>
        <div className="overflow-x-auto">
          <table className="table-auto text-sm border mb-4">
            <thead>
              <tr>
                <th className="border px-2">Klartext:</th>
                {klartextAlphabet.map((_, i) => (
                  <th key={i} className="border px-1 py-1 w-8">
                    <input
                      type="text"
                      value={klartextZuordnung[i] || ""}
                      onChange={(e) => updateKlartextBuchstabe(i, e.target.value)}
                      maxLength={1}
                      className="w-6 text-black text-center"
                    />
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              <tr>
                <th className="border px-2">Geheimtext:</th>
                {klartextAlphabet.map((char, i) => (
                  <td key={i} className="border px-1 py-1 text-center w-8">{char}</td>
                ))}
              </tr>
            </tbody>
          </table>
        </div>
        <p className="mb-1 font-bold">Entschlüsselter Text mit deinem Alphabet:</p>
        <div className="bg-white/10 p-4 rounded text-sm mb-2 max-h-36 overflow-y-auto">
        {applyErsetzung(ersetzenText, klartextZuordnung)}
        </div>

        <button
          onClick={() => setKlartextZuordnung(haeufigkeitsbasiertesAlphabet())}
          className="mt-2 px-4 py-2 border border-white text-white rounded hover:bg-white hover:text-black transition"
        >
          Zuordnung aufgrund der Häufigkeiten
        </button>
      </div>

      <div className="mb-8">
        <h2 className="text-xl font-bold heading-style mb-2">Vergleich der Sicherheit</h2>
        <p>
          Du hast herausgefunden: Das Caesar-Verfahren ist leicht durch Brute-Force knackbar – es gibt nur 26 mögliche Schlüssel.
          Beim Ersetzungsverfahren sind es 26! Möglichkeiten – viel zu viele zum Raten.
          Aber auch hier hilft die Häufigkeitsanalyse - aber nur, wenn der Text lang genug ist, um die Häufigkeiten repräsentativ abzuilden.
        </p>
      </div>

      <WeiterButton to="/level2/fachkonzepte" />
    </div>
  );
}
